pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        // Mint some tokens first so we have something to burn
        c.mintToken(address(this), 1000);
        // Now burn 100 tokens
        c.burn(100);
        // The reference contract would have totalSupply = 900, bug has totalSupply = 1000
        assertTrue(c.totalSupply() == 900);
    }
}

