// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        // Mint 100 tokens to address(0x1)
        address target = address(0x1);
        c.mintToken(target, 100);
        // Owner burns 150 tokens (owner has 100 from initialSupply = 0? Wait, constructor totalSupply is initialSupply * 10**0 = 0, owner balance = 0)
        // Actually the constructor sets totalSupply = initialSupply * 1 = 0, owner balance = 0
        // After minting 100 to target, owner still has 0, totalSupply becomes 100 (in reference) or 0 (in buggy)
        // Owner tries to burn 150, should fail for reference (balance 0), but for buggy totalSupply is 0, but burn only checks balanceOf[msg.sender] >= _value, which is false, so both revert?
        // Need a scenario where reference reverts and buggy succeeds. Let's instead check totalSupply after operations.
        // Reset: Start with initialSupply=1000 so owner has 1000 tokens.
        // But we must use the given setUp line. So we deploy with (0,0,0).
        // Then we mint 100 to target, then owner burns 50? Let's check: reference: totalSupply starts 0, mintToken adds 100 => totalSupply=100, owner balance=0, burn(50) revert (balance < 50). Buggy: totalSupply stays 0, owner balance=0, burn(50) also revert. So no divergence.
        // Alternative: After minting, owner transfers tokens? But owner has 0.
        // Actually the only way to get a difference is if a user has enough balance to burn in buggy but not in reference due to totalSupply update.
        // Let's try: deploy with (100, "", "") => initial supply 100, owner has 100.
        // But setUp is fixed: new C(0,0,0). So owner has 0.
        // We need to give owner tokens via transfer from someone else? No one else has tokens.
        // Or mint to owner: c.mintToken(address(this), 100); then owner has 100.
        // Then burn 50: reference totalSupply = 100-50=50, buggy totalSupply = 100 (mint didn't update) - 50 = 50? Wait burn subtracts totalSupply too, so in buggy: totalSupply = 0 - 50? No, totalSupply started 0, mint didn't change, so totalSupply still 0, then burn subtracts 50 => underflow? In Solidity 0.8, subtraction underflow reverts. So reference succeeds, buggy reverts.
        // That's a divergence: reference succeeds with totalSupply=50, buggy reverts.
        // Let's use that: mint 100 to owner, burn 50.
        c.mintToken(address(this), 100);
        // Now burn 50
        try c.burn(50) {
            // reference succeeds
            assertTrue(c.totalSupply() == 50);
        } catch {
            // buggy reverts
            assertTrue(false);
        }
    }
}

