// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        // Setup: owner is the test contract (address(this))
        address owner = address(this);

        // Mint 100 tokens to owner so burn can work
        c.mintToken(owner, 100);

        // Call burn(100) - should succeed in reference but revert in mutant
        bool success;
        try c.burn(100) {
            success = true;
        } catch {
            success = false;
        }

        // In reference: burn succeeds => owner remains unchanged
        // In mutant: burn reverts => owner still unchanged
        // The observable difference is that after the call:
        // Reference: c.owner() == address(this)
        // Mutant: burn reverts, but owner getter STILL returns address(this)
        // Actually, the mutant's require(msg.sender != owner) makes burn always revert,
        // but the owned() function is NOT called by burn. The onlyOwner modifier in burn
        // uses require(msg.sender == owner) directly, not the owned() function.
        // So let's think again about the actual difference.

        // The owned() function is defined but never used as a modifier.
        // The onlyOwner modifier is separate. So the mutant only changes an unused function.
        // To make this test work, we need a scenario where owned() is called.
        // Since no function calls owned(), the only observable difference is:
        // - Reference: owned() returns nothing but does not revert when called by owner
        // - Mutant: owned() reverts when called by owner

        // So we test calling owned() directly.
        bool ownedSuccess;
        // Reset state: just call owned() as owner
        // In reference: require(msg.sender == owner) is true => call succeeds
        // In mutant: require(msg.sender != owner) is false => call reverts
        try this.callOwned() {
            ownedSuccess = true;
        } catch {
            ownedSuccess = false;
        }
        // But we can't call c.owned() directly because it's public but not a view.
        // Let's use a different approach:
    }
    function callOwned() public {
        c.owned();
    }
}

