        // Actually we need to test burn() after ownership change. Let owner transfer ownership to alice first.
        // But the bug is in owned() affecting onlyOwner modifier. 
        // So: set up: owner = this (the test contract), then call burn as owner.
        // In reference, burn succeeds; in buggy, owned() require fails (since owner != msg.sender caused by mutation), so burn reverts.
        bool ok;
        try c.burn(100) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

