pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        // Deploy with 0 totalSupply; mint some tokens to owner so burn is possible
        // But to avoid minting complexity, we simply have owner do a burn of 0 (or mint first).
        // Simpler: deploy with initialSupply = 1000 => owner gets 1000*10^0 = 1000 tokens.
        // But setUp uses new C(0,0,0) => totalSupply=0, owner balance=0, burn will revert for owner due to balance requirement.
        // So we need to mint before burn.
        // Alternatively deploy differently? Hard rule says deploy in setUp using new C(0,0,0). So we must work with that.
        // With totalSupply=0, owner cannot burn because balanceOf[owner]=0 => require fails.
        // So we need to mint first via mintToken (onlyOwner).
        vm.startPrank(address(0xdead)); // not owner, will fail mint, so use owner
        vm.stopPrank();
        // Actually deployer is owner (msg.sender = address(this) in setUp).
        // So inside test, we are address(this) which is the owner.
        // Mint some tokens to a non-owner account so they can attempt burn.
        c.mintToken(address(0x1234), 200);
        uint256 totalSupplyBefore = c.totalSupply();
        // Non-owner tries burn
        vm.prank(address(0x1234));
        // On reference (onlyOwner modifier), burn reverts; on buggy, it succeeds.
        // We catch revert via try/catch.
        bool ok;
        try c.burn(100) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: burn reverts => ok = false => totalSupply unchanged
        // Bug: burn succeeds => ok = true => totalSupply decreases
        // The property: on reference totalSupplyBefore equals totalSupply after call, on bug totalSupplyBefore != totalSupply after call.
        // Assert that totalSupply did NOT change (reference behavior).
        assertTrue(c.totalSupply() == totalSupplyBefore, "totalSupply should not change because burn should revert");
    }
}

